process.env.TZ = "America/New_York";

import assert from "node:assert/strict";
import { test } from "node:test";
import { parseBody } from "../src/data.ts";
import { parseFeed } from "../src/sources/feed.ts";

/** valueOf and parseBody take the time they read at; these read at a fixed one. */
const TEST_NOW = new Date(2026, 10, 18, 12, 0);

const LONG = `${"Word ".repeat(120)}end`;

const RSS = `<?xml version="1.0" encoding="UTF-8"?>
<?xml-stylesheet type="text/xsl" href="/feed.xsl"?>
<!-- generated by hnrss -->
<rss version="2.0" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:content="http://purl.org/rss/1.0/modules/content/">
<channel>
  <title>Hacker News: Front Page</title>
  <link>https://news.ycombinator.com/</link>
  <atom:link href="https://hnrss.org/frontpage" rel="self" type="application/rss+xml"/>
  <item>
    <title>Show HN: A tiny &amp; fast parser</title>
    <link>https://example.com/parser?a=1&amp;b=2</link>
    <pubDate>Tue, 17 Nov 2026 15:04:05 GMT</pubDate>
    <dc:creator>jane</dc:creator>
    <comments>https://news.ycombinator.com/item?id=1</comments>
    <guid isPermaLink="false">https://news.ycombinator.com/item?id=1</guid>
    <description><![CDATA[<p>Article URL: <a href="https://example.com/parser?a=1&amp;b=2">https://example.com/parser</a></p>
<p>Points: 120 &amp; counting</p>]]></description>
  </item>
  <item>
    <title><![CDATA[Q&A: the R&D budget]]></title>
    <link>https://example.com/budget</link>
    <pubDate>Wed, 18 Nov 2026 07:30:00 -0500</pubDate>
    <author>editor@example.com (Pat Editor)</author>
    <guid>budget-2026</guid>
    <description>&lt;p&gt;It&amp;#8217;s &lt;b&gt;big&lt;/b&gt;&amp;nbsp;news&amp;#x2014;really &amp;lt;3 &amp;amp; &amp;hellip;&lt;/p&gt;&lt;p&gt;Second paragraph.&lt;/p&gt;</description>
  </item>
  <item>
    <title>Long one</title>
    <link>https://example.com/long</link>
    <pubDate>sometime soon</pubDate>
    <content:encoded><![CDATA[<div>${LONG}</div>]]></content:encoded>
  </item>
  <item>
    <title>No link, no date</title>
  </item>
</channel>
</rss>`;

test("RSS 2.0: titles, links, dates, authors, ids and summaries, in feed order", () => {
  const rows = parseFeed(RSS);
  assert.deepEqual(rows.map((r) => r.title), ["Show HN: A tiny & fast parser", "Q&A: the R&D budget", "Long one", "No link, no date"]);
  assert.deepEqual(rows[0], {
    title: "Show HN: A tiny & fast parser",
    link: "https://example.com/parser?a=1&b=2",
    date: "2026-11-17T10:04",
    summary: "Article URL: https://example.com/parser Points: 120 & counting",
    author: "jane",
    id: "https://news.ycombinator.com/item?id=1",
  });
  assert.deepEqual(rows[1], {
    title: "Q&A: the R&D budget",
    link: "https://example.com/budget",
    date: "2026-11-18T07:30",
    summary: "It’s big news—really <3 & &hellip; Second paragraph.",
    author: "editor@example.com (Pat Editor)",
    id: "budget-2026",
  });
});

test("a summary is capped at 500 characters; an unreadable date stays as written; missing parts are empty", () => {
  const [, , long, bare] = parseFeed(RSS);
  assert.equal(String(long.summary).length, 500);
  assert.ok(String(long.summary).startsWith("Word Word Word "));
  assert.ok(String(long.summary).endsWith("…"));
  assert.equal(long.date, "sometime soon");
  assert.deepEqual(bare, { title: "No link, no date", link: "", date: "", summary: "", author: "", id: "" });
});

const ATOM = `<?xml version="1.0" encoding="utf-8"?>
<feed xmlns="http://www.w3.org/2005/Atom">
  <title>Notes</title>
  <link href="https://blog.example.org/" rel="alternate"/>
  <link href="https://blog.example.org/feed" rel="self"/>
  <id>https://blog.example.org/</id>
  <updated>2026-11-16T00:00:00Z</updated>
  <entry>
    <title>Dependency graph</title>
    <link href="https://blog.example.org/feed/1.json" rel="related"/>
    <link rel="alternate" href='https://blog.example.org/1?x=1&amp;y=2' type="text/html"/>
    <link rel="enclosure" href="https://blog.example.org/1.png" type="image/png"/>
    <updated>2026-11-16T05:00:00Z</updated>
    <published>2026-11-01T05:00:00Z</published>
    <id>tag:blog.example.org,2026:1</id>
    <author><name>Alex Doe</name><uri>https://blog.example.org/alex</uri></author>
    <summary type="html">&lt;img src='https://blog.example.org/1.png' alt='x' /&gt;A &lt;a href="https://x.test"&gt;link&lt;/a&gt; in a summary</summary>
  </entry>
  <entry>
    <title type="text">Only a file link</title>
    <link rel="enclosure" href="https://blog.example.org/2.mp3"/>
    <published>2026-11-10</published>
    <id>tag:blog.example.org,2026:2</id>
    <content type="xhtml"><div xmlns="http://www.w3.org/1999/xhtml"><p>Hello <b>wor</b>ld.</p><p>Second.</p></div></content>
  </entry>
  <entry>
    <title>A link without rel</title>
    <link href="https://blog.example.org/3"></link>
    <id>tag:blog.example.org,2026:3</id>
  </entry>
</feed>`;

test("Atom: the page link is preferred among several, the author is inside <author>", () => {
  const rows = parseFeed(ATOM);
  assert.deepEqual(rows[0], {
    title: "Dependency graph",
    link: "https://blog.example.org/1?x=1&y=2",
    date: "2026-11-16T00:00",
    summary: "A link in a summary",
    author: "Alex Doe",
    id: "tag:blog.example.org,2026:1",
  });
  // A date-only value is that day, not a time shifted by the zone; the content stands in for a missing summary.
  assert.deepEqual(rows[1], {
    title: "Only a file link",
    link: "https://blog.example.org/2.mp3",
    date: "2026-11-10T00:00",
    summary: "Hello world. Second.",
    author: "",
    id: "tag:blog.example.org,2026:2",
  });
  assert.equal(rows[2].link, "https://blog.example.org/3");
  assert.equal(rows.length, 3);
});

test("RSS 1.0 (RDF): items sit beside the channel, and rdf:about names them", () => {
  const rdf = `<?xml version="1.0"?>
<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#" xmlns="http://purl.org/rss/1.0/" xmlns:dc="http://purl.org/dc/elements/1.1/">
  <channel rdf:about="https://example.org/"><title>Example</title><link>https://example.org/</link>
    <items><rdf:Seq><rdf:li rdf:resource="https://example.org/a"/></rdf:Seq></items></channel>
  <item rdf:about="https://example.org/a">
    <title>First</title><link>https://example.org/a</link><description>Plain text</description>
    <dc:creator>Sam</dc:creator><dc:date>2026-11-12T09:30:00+01:00</dc:date>
  </item>
</rdf:RDF>`;
  assert.deepEqual(parseFeed(rdf), [{
    title: "First", link: "https://example.org/a", date: "2026-11-12T03:30", summary: "Plain text", author: "Sam", id: "https://example.org/a",
  }]);
});

test("parseBody takes a feed by what the body starts with, past a declaration, comments and a stylesheet", () => {
  assert.equal((parseBody(RSS, "application/rss+xml", TEST_NOW) as unknown[]).length, 4);
  assert.equal((parseBody(ATOM, "", TEST_NOW) as unknown[]).length, 3);
  assert.equal((parseBody(`﻿\n${ATOM}`, "text/xml", TEST_NOW) as unknown[]).length, 3);
  assert.equal((parseBody("<feed><entry><title>t</title></entry></feed>", "", TEST_NOW) as unknown[]).length, 1);
  assert.equal((parseBody('<rdf:RDF xmlns:rdf="x"><item><title>t</title></item></rdf:RDF>', "", TEST_NOW) as unknown[]).length, 1);
});

test("parseBody leaves other bodies to the JSON, CSV and text rules", () => {
  assert.equal(parseBody("<html><body>Hi</body></html>", "text/html", TEST_NOW), "<html><body>Hi</body></html>");
  assert.equal(parseBody("<rssfeed/>", "", TEST_NOW), "<rssfeed/>");
  assert.deepEqual(parseBody('{"a":1}', "application/json", TEST_NOW), { a: 1 });
  assert.deepEqual(parseBody("a,b\n1,2\n", "text/csv", TEST_NOW), [{ a: 1, b: 2 }]);
});

test("a summary drops the text of script and style elements, not just their tags", () => {
  const summary = (description: string) => String(parseFeed(`<rss><channel><item><title>t</title><description>${description}</description></item></channel></rss>`)[0].summary);
  assert.equal(summary("&lt;p&gt;Hello&lt;/p&gt;&lt;script&gt;alert(1)&lt;/script&gt;&lt;p&gt;World&lt;/p&gt;"), "Hello World");
  assert.equal(summary('<![CDATA[<p>Hi</p><SCRIPT type="text/javascript">var a = 1 < 2;\nfoo()</SCRIPT><style>p { color: red }</style><p>there</p>]]>'), "Hi there");
  assert.equal(summary("<![CDATA[a<script>1</script>b<script>2</script>c]]>"), "abc");
  // A script with no end runs to the end of the text; one that closes itself holds nothing; other tags that start alike stay.
  assert.equal(summary("<![CDATA[Text <script>unclosed code]]>"), "Text");
  assert.equal(summary('<![CDATA[Before <script src="x.js"/> after <style/> end]]>'), "Before after end");
  assert.equal(summary("<![CDATA[<scripty>keep</scripty> <b>bold</b>]]>"), "keep bold");
});

test("a hostile body of about 1 MB is read in well under a second, whatever it repeats", () => {
  const n = 1_000_000;
  const rep = (s: string) => s.repeat(Math.ceil(n / s.length));
  const rss = (inside: string) => `<rss><channel>${inside}</channel></rss>`;
  const item = (inside: string) => rss(`<item><title>t</title>${inside}</item>`);
  const cases: [string, string, string][] = [
    ["commas with no line break", rep(","), "text/plain"],
    ["<item> never closed", rss(rep("<item>")), ""],
    ["<item with no >", rss(rep("<item ")), ""],
    ["<title> never closed", item(rep("<title>")), ""],
    ["<link> never closed", item(rep("<link>")), ""],
    ["<link with no >", item(rep("<link ")), ""],
    ["one long link attribute", item(`<link ${rep("a")}/>`), ""],
    ["one long item attribute", rss(`<item ${rep("a")}><title>t</title></item>`), ""],
    ["CDATA never closed", item(`<description>${rep("<![CDATA[")}</description>`), ""],
    ["<script never closed", item(`<description><![CDATA[${rep("<script ")}]]></description>`), ""],
    ["<a with no > in a summary", item(`<description>${rep("&lt;a")}</description>`), ""],
    ["</p with no > in a summary", item(`<description><![CDATA[${rep("</p ")}]]></description>`), ""],
    ["calendar events never ended", `BEGIN:VCALENDAR\n${rep("BEGIN:VEVENT\n")}`, "text/calendar"],
    ["deeply nested JSON", `${"[".repeat(n / 2)}${"]".repeat(n / 2)}`, "application/json"],
  ];
  for (const [what, body, type] of cases) {
    const t0 = performance.now();
    try {
      parseBody(body, type, new Date(2026, 10, 19));
    } catch {
      // Refusing it is fine too; taking long isn't.
    }
    const ms = performance.now() - t0;
    assert.ok(ms < 250, `${what}: ${Math.round(ms)} ms`);
  }
});
